-- Fictitious requests make each workflow available for the team's local demo.
-- Dates are relative to first installation; saved records are never reset on restart.
SELECT user_id, YEAR(CURRENT_DATE)-1, CASE WHEN designation='Administrative' THEN 5 ELSE 10 END, 2000
FROM users WHERE role IN ('STAFF','MANAGER');


